//! Whole-file byte-compare control on the narrowed X2D fixture
//! (`tests/parity/validation/multi-filament-bridge-anchor-narrowed.3mf` —
//! X2D, two filaments, `sparse_infill_filament_id=2`, tower off, timelapse
//! off, Normal Lift, z_hop=0, disable_m73=1). The only normalized line is
//! the `; generated by` banner: upstream stamps its own name/timestamp,
//! ares stamps `Ares 2.4.2`.
//!
//! This test PASSES on main `458938aa4` — the residual clusters recorded
//! for this fixture (M73/time model, `M625`/object-stop ordering, SEMM
//! `M104`, two-step retract) were all closed by merged slices
//! (`01c0a5de8`, `4f02cbe8a`, `9e3e81837`, and the placeholder family).
//! It is a control guarding that byte parity, not a RED.

use std::fs;

use crate::runner::{OrcaRunner, stages};

const INPUT: &[u8] =
    include_bytes!("../../../../tests/parity/validation/multi-filament-bridge-anchor-narrowed.3mf");
const INPUT_SHA256: &str = "22d3813ddbbfbc40bd3955fb35d5f6d19b7d8ee23472e7aa2e354e50a23cfe82";

#[test]
fn orca_parity_narrowed_x2d_whole_file() {
    use sha2::{Digest, Sha256};
    assert_eq!(
        Sha256::digest(INPUT)
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>(),
        INPUT_SHA256
    );
    let Some(runner) = OrcaRunner::from_env().unwrap_or_else(|error| panic!("{error}")) else {
        return;
    };
    let directory = tempfile::Builder::new()
        .prefix("narrowed-x2d-whole-file-")
        .tempdir()
        .unwrap()
        .keep();
    let input = directory.join("input.3mf");
    fs::write(&input, INPUT).unwrap();
    let output = directory.join("orca");
    fs::create_dir(&output).unwrap();
    stages::run(
        runner.bin(),
        [
            "--slice".to_owned(),
            "0".to_owned(),
            "--outputdir".to_owned(),
            output.to_str().unwrap().to_owned(),
            input.to_str().unwrap().to_owned(),
        ],
        stages::Stage::Slice,
        &directory,
    )
    .unwrap();
    let reference = stages::read(&output.join("plate_1.gcode"), stages::Stage::Slice).unwrap();

    let actual_bytes = tokio::runtime::Builder::new_current_thread()
        .build()
        .unwrap()
        .block_on(ares_core::slice_project(
            INPUT,
            ares_core::GenerationMetadata::deterministic(2026, 8, 27, 0, 0, 0),
            ares_core::SlicerContext::new(0),
        ))
        .unwrap();

    // Normalize only the `; generated by` banner line — upstream stamps
    // its own name and wall-clock; everything else must match byte-for-byte.
    let normalize = |bytes: &[u8]| -> Vec<u8> {
        let text = String::from_utf8(bytes.to_vec()).unwrap();
        text.lines()
            .map(|line| {
                if line.starts_with("; generated by") {
                    "; generated by"
                } else {
                    line
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
            .into_bytes()
    };
    assert_eq!(
        normalize(&actual_bytes),
        normalize(&reference),
        "narrowed X2D whole-file diverged; {directory:?}"
    );
}
